  const input = htl.html`&lt;input class="pattern-filter-input" type="search" placeholder="Search registration, country, prefix, or category"&gt;`;
  const label = htl.html`&lt;label class="pattern-filter-label"&gt;&lt;span&gt;Filter&lt;/span&gt;${input}&lt;/label&gt;`;
